const express = require('express');
const net = require('net');

const app = express();

const DEFAULT_DB_CHECK_TIMEOUT_MS = Number(process.env.DB_HEALTH_TIMEOUT_MS || 1000);

function getPostgresConnectionOptions() {
  if (process.env.DATABASE_URL) {
    const databaseUrl = new URL(process.env.DATABASE_URL);

    return {
      connectionString: process.env.DATABASE_URL,
      host: databaseUrl.hostname,
      port: Number(databaseUrl.port || 5432),
    };
  }

  return {
    host: process.env.PGHOST || 'localhost',
    port: Number(process.env.PGPORT || 5432),
    user: process.env.PGUSER,
    password: process.env.PGPASSWORD,
    database: process.env.PGDATABASE,
  };
}

function waitForTcpConnection({ host, port }, timeoutMs = DEFAULT_DB_CHECK_TIMEOUT_MS) {
  return new Promise((resolve, reject) => {
    const socket = net.createConnection({ host, port });

    const fail = (error) => {
      socket.destroy();
      reject(error);
    };

    socket.setTimeout(timeoutMs);
    socket.once('connect', () => {
      socket.end();
      resolve();
    });
    socket.once('timeout', () => fail(new Error('Postgres health check timed out')));
    socket.once('error', fail);
  });
}

async function checkPostgres() {
  const connectionOptions = getPostgresConnectionOptions();

  try {
    // Prefer a real Postgres query when the optional pg client is installed.
    // Falling back to a TCP check keeps this lightweight in environments that
    // only need to verify that the database endpoint is reachable.
    const { Client } = require('pg');
    const client = new Client({
      ...connectionOptions,
      connectionTimeoutMillis: DEFAULT_DB_CHECK_TIMEOUT_MS,
    });

    try {
      await client.connect();
      await client.query('SELECT 1');
    } finally {
      await client.end().catch(() => undefined);
    }
  } catch (error) {
    if (error && error.code !== 'MODULE_NOT_FOUND') {
      throw error;
    }

    await waitForTcpConnection(connectionOptions);
  }
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/healthz', async (req, res) => {
  const dbHealthCheck = app.locals.dbHealthCheck || checkPostgres;

  try {
    await dbHealthCheck();
    res.status(200).json({ db: 'ok' });
  } catch (error) {
