const express = require('express');

let postgresPool;

function getPostgresPool() {
  if (!process.env.DATABASE_URL) {
    throw new Error('DATABASE_URL is not configured');
  }

  if (!postgresPool) {
    // Load pg lazily so importing the app does not require a database driver
    // unless the readiness probe is exercised with the default checker.
    const { Pool } = require('pg');
    postgresPool = new Pool({ connectionString: process.env.DATABASE_URL });
  }

  return postgresPool;
}

async function checkPostgres() {
  const pool = getPostgresPool();
  const client = await pool.connect();

  try {
    await client.query('SELECT 1');
  } finally {
    client.release();
  }
}

function createApp({ dbCheck = checkPostgres } = {}) {
  const app = express();

  app.get('/healthz', async (req, res) => {
    try {
      await dbCheck();
      res.status(200).json({ db: 'ok' });
    } catch (error) {
      res.status(503).json({ db: 'error' });
    }
  });

  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  app.get('/users', (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  return app;
}

const app = createApp();

if (require.main === module) {
  app.listen(3000, () => {
