    const { Pool } = require('pg');
    pgPool = new Pool({
      connectionString: process.env.DATABASE_URL,
      connectionTimeoutMillis: Number(process.env.DB_HEALTHCHECK_TIMEOUT_MS || 2000),
      query_timeout: Number(process.env.DB_HEALTHCHECK_TIMEOUT_MS || 2000),
